"use client";

import { useId, useState } from "react";

import { Switch } from "@/components/motion/switch";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { formatMoney } from "../lib/format";
import { type Status, STATUS_SURFACE, STATUS_TEXT } from "../lib/status";
import { BlockFrame } from "../parts/block-frame";
import { RollingText } from "../parts/rolling-text";
import { ChatIcon, MailIcon, StopIcon, TextIcon } from "./icons";
import {
  CHANNELS,
  type ChannelId,
  forecastFor,
  SPENT,
  START_ALERT,
  START_BUDGET,
} from "./spend-alert/data";
import { SpendBar } from "./spend-alert/spend-bar";

const CHANNEL_ICONS = {
  email: MailIcon,
  chat: ChatIcon,
  text: TextIcon,
} satisfies Record<ChannelId, typeof MailIcon>;

/** The state the pill shows, with the word for it. */
interface CardState {
  status: Status;
  word: string;
}

/** The card's state from spend, forecast and alert level, with its word. */
function readState(
  spent: number,
  forecast: number,
  budget: number,
  alertAmount: number,
) {
  if (spent >= budget)
    return { status: "bad", word: "Over budget" } satisfies CardState;
  if (forecast >= alertAmount)
    return { status: "watch", word: "Alert likely" } satisfies CardState;
  return { status: "good", word: "On track" } satisfies CardState;
}

/**
 * A monthly budget for reminder texts with an alert set right on the spend
 * bar. Drag or key the alert line, change the budget, pick where the alert
 * goes, and read the message it will send.
 */
export function SpendAlert({ className }: { className?: string }) {
  const [budgetText, setBudgetText] = useState(String(START_BUDGET));
  const [alert, setAlert] = useState(START_ALERT);
  const [channels, setChannels] = useState<Record<ChannelId, boolean>>({
    email: true,
    chat: true,
    text: false,
  });
  const [hardStop, setHardStop] = useState(false);
  const titleId = useId();
  const budgetId = useId();

  const budget = Math.max(
    1,
    Number(budgetText.replace(/[^\d]/g, "")) || START_BUDGET,
  );
  const forecast = forecastFor(SPENT);
  const alertAmount = Math.round((budget * alert) / 100);
  const state = readState(SPENT, forecast, budget, alertAmount);
  const active = CHANNELS.filter((channel) => channels[channel.id]);
  const preview = `Harbour Street clinic has reached ${alert}% (${formatMoney(alertAmount)}) of its ${formatMoney(budget)} reminder text budget for November. At this pace the month ends near ${formatMoney(forecast)}.${hardStop ? " Texts pause at 100% until Dec 1." : ""}`;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Reminder text budget
          </h2>
          <p className="text-sm text-muted-foreground">
            Harbour Street clinic, every practitioner
          </p>
        </div>
        <span
          role="status"
          className={cn(
            "rounded-full px-2.5 py-1 text-xs font-medium",
            STATUS_SURFACE[state.status],
            STATUS_TEXT[state.status],
          )}
        >
          {state.word}
        </span>
      </header>

      <div className="flex flex-col gap-6 p-5">
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div className="flex flex-col gap-1.5">
            <label htmlFor={budgetId} className="text-sm font-medium">
              Monthly budget
            </label>
            <div className="flex items-center gap-1.5">
              <span
                aria-hidden="true"
                className="text-sm text-muted-foreground"
              >
                $
              </span>
              <Input
                id={budgetId}
                inputMode="numeric"
                value={budgetText}
                aria-describedby={`${budgetId}-reset`}
                onChange={(event) =>
                  setBudgetText(
                    event.target.value.replace(/[^\d]/g, "").slice(0, 5),
                  )
                }
                className="w-28"
              />
            </div>
            <p
              id={`${budgetId}-reset`}
              className="text-xs text-muted-foreground"
            >
              Resets on Dec 1
            </p>
          </div>
          <dl className="flex gap-6 text-sm">
            <div>
              <dt className="text-muted-foreground">Spent</dt>
              <dd className="text-lg font-semibold">
                <RollingText text={formatMoney(SPENT)} />
              </dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Forecast</dt>
              <dd className="text-lg font-semibold">
                <RollingText text={formatMoney(forecast)} />
              </dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Alert at</dt>
              <dd className="text-lg font-semibold text-chart-4">
                <RollingText text={`${alert}%`} />
              </dd>
            </div>
          </dl>
        </div>

        <div className="flex flex-col gap-3">
          <SpendBar
            spent={SPENT}
            forecast={forecast}
            budget={budget}
            alert={alert}
            onAlert={setAlert}
          />
          <ul className="flex flex-wrap gap-x-5 gap-y-1 text-xs text-muted-foreground">
            <li className="flex items-center gap-1.5">
              <span
                aria-hidden="true"
                className="size-2.5 rounded-full bg-chart-1"
              />
              Spent, {formatMoney(SPENT)}
            </li>
            <li className="flex items-center gap-1.5">
              <span
                aria-hidden="true"
                className="size-2.5 rounded-full bg-chart-1 opacity-35"
              />
              Forecast, {formatMoney(forecast)}
            </li>
            <li className="flex items-center gap-1.5">
              <span
                aria-hidden="true"
                className="h-2.5 w-0.5 rounded-full bg-chart-4"
              />
              Alert, <RollingText text={formatMoney(alertAmount)} />
            </li>
          </ul>
        </div>

        <fieldset className="flex flex-col">
          <legend className="mb-1 text-sm font-semibold">
            Send the alert to
          </legend>
          {CHANNELS.map((channel) => {
            const Icon = CHANNEL_ICONS[channel.id];
            const id = `${budgetId}-${channel.id}`;
            return (
              <div
                key={channel.id}
                className="flex items-center justify-between gap-3 border-b border-border py-3"
              >
                <span className="flex min-w-0 items-center gap-3">
                  <span
                    aria-hidden="true"
                    className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted"
                  >
                    <Icon className="size-4" />
                  </span>
                  <span className="flex min-w-0 flex-col">
                    <label
                      htmlFor={id}
                      className="cursor-pointer text-sm font-medium"
                    >
                      {channel.label}
                    </label>
                    <span
                      id={`${id}-to`}
                      className="truncate text-xs text-muted-foreground"
                    >
                      {channel.destination}
                    </span>
                  </span>
                </span>
                <Switch
                  id={id}
                  aria-describedby={`${id}-to`}
                  checked={channels[channel.id]}
                  onCheckedChange={(on) =>
                    setChannels((current) => ({ ...current, [channel.id]: on }))
                  }
                />
              </div>
            );
          })}
          <div className="flex items-center justify-between gap-3 py-3">
            <span className="flex min-w-0 items-center gap-3">
              <span
                aria-hidden="true"
                className={cn(
                  "flex size-8 shrink-0 items-center justify-center rounded-lg",
                  hardStop ? STATUS_SURFACE.bad : "bg-muted",
                )}
              >
                <StopIcon
                  className={cn(
                    "size-4",
                    hardStop ? STATUS_TEXT.bad : undefined,
                  )}
                />
              </span>
              <span className="flex min-w-0 flex-col">
                <label
                  htmlFor={`${budgetId}-stop`}
                  className="cursor-pointer text-sm font-medium"
                >
                  Hard stop
                </label>
                <span
                  id={`${budgetId}-stop-helper`}
                  className="text-xs text-muted-foreground"
                >
                  Pause reminder texts once the budget is spent.
                </span>
              </span>
            </span>
            <Switch
              id={`${budgetId}-stop`}
              aria-describedby={`${budgetId}-stop-helper`}
              checked={hardStop}
              onCheckedChange={setHardStop}
            />
          </div>
        </fieldset>

        <section
          aria-labelledby={`${titleId}-preview`}
          className="flex flex-col gap-2"
        >
          <h3 id={`${titleId}-preview`} className="text-sm font-semibold">
            Message preview
          </h3>
          <div className="rounded-xl border border-border p-4">
            <p className="text-xs text-muted-foreground">
              {active.length === 0
                ? "No channel chosen, so nobody gets this alert."
                : `To ${active.map((channel) => channel.label.toLowerCase()).join(", ")}`}
            </p>
            <p className="mt-1.5 text-sm">{preview}</p>
          </div>
        </section>
      </div>
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

