/** Spend so far this month on reminder texts. */
export const SPENT = 84;

/** The share of the month that has passed, for the forecast. */
export const MONTH_PASSED = 11 / 30;

/** The month's forecast at the pace so far. */
export const forecastFor = (spent: number) => Math.round(spent / MONTH_PASSED);

/** The budget when the card loads. */
export const START_BUDGET = 200;

/** The alert level when the card loads, in percent of the budget. */
export const START_ALERT = 80;

/** The marks on the bar, in percent. Page keys jump between them. */
export const MARKERS = [25, 50, 75, 90, 100];

/** The lowest and highest alert level, in percent. */
export const ALERT_MIN = 10;
/** The highest alert level, in percent. */
export const ALERT_MAX = 100;

/** The channels an alert can reach, with where each one goes. */
export const CHANNELS = [
  { id: "email", label: "Email", destination: "billing@harbourstreet.clinic" },
  { id: "chat", label: "Team chat", destination: "#front-desk" },
  { id: "text", label: "Text message", destination: "+44 7700 900 412" },
] as const;

/** A channel id. */
export type ChannelId = (typeof CHANNELS)[number]["id"];

/** The level of the alert after an arrow, Page or Home or End key, or null for another key. */
export function nextAlert(key: string, shift: boolean, value: number) {
  const clamp = (next: number) => Math.min(ALERT_MAX, Math.max(ALERT_MIN, next));
  if (key === "ArrowRight" || key === "ArrowUp") return clamp(value + (shift ? 10 : 1));
  if (key === "ArrowLeft" || key === "ArrowDown") return clamp(value - (shift ? 10 : 1));
  if (key === "PageUp") return MARKERS.find((mark) => mark > value) ?? ALERT_MAX;
  if (key === "PageDown") return [...MARKERS].reverse().find((mark) => mark < value) ?? ALERT_MIN;
  if (key === "Home") return ALERT_MIN;
  if (key === "End") return ALERT_MAX;
  return null;
}

"use client";

import { type PointerEvent, useEffect, useRef, useState, type CSSProperties } from "react";

import { cn } from "@/lib/utils";

import { formatMoney } from "../../lib/format";
import { ALERT_MAX, ALERT_MIN, MARKERS, nextAlert } from "./data";

/** Props for the spend bar with its alert line. */
export interface SpendBarProps {
  spent: number;
  forecast: number;
  budget: number;
  /** The alert level, in percent of the budget. */
  alert: number;
  onAlert: (percent: number) => void;
}

/**
 * Spend and forecast as two fills on one bar, with marks at set shares of the
 * budget and a draggable alert line. The fills grow in once the bar scrolls
 * into view. The thumb follows the pointer exactly while dragged and glides
 * on clicks and keys. Arrows move 1 percent, Shift 10; Page keys jump between
 * marks; Home and End set 10 and 100 percent.
 */
export function SpendBar({ spent, forecast, budget, alert, onAlert }: SpendBarProps) {
  const trackRef = useRef<HTMLDivElement>(null);
  const [seen, setSeen] = useState(false);
  const [dragging, setDragging] = useState(false);
  const top = Math.max(budget, forecast) * 1.1;
  const at = (amount: number) => `${Math.min(100, (amount / top) * 100)}%`;
  const alertAmount = (budget * alert) / 100;

  useEffect(() => {
    const track = trackRef.current;
    if (!track) return;
    const observer = new IntersectionObserver(([entry]) => {
      if (entry?.isIntersecting) {
        setSeen(true);
        observer.disconnect();
      }
    });
    observer.observe(track);
    return () => observer.disconnect();
  }, []);

  const fromPointer = (event: PointerEvent<HTMLElement>) => {
    const box = trackRef.current?.getBoundingClientRect();
    if (!box || box.width === 0) return;
    const ratio = Math.min(1, Math.max(0, (event.clientX - box.left) / box.width));
    const percent = Math.round(((ratio * top) / budget) * 100);
    onAlert(Math.min(ALERT_MAX, Math.max(ALERT_MIN, percent)));
  };

  return (
    <div className="flex flex-col gap-2">
      <div
        ref={trackRef}
        className="relative h-10 cursor-pointer touch-pan-y"
        onPointerDown={(event) => {
          event.currentTarget.setPointerCapture(event.pointerId);
          setDragging(true);
          fromPointer(event);
        }}
        onPointerMove={(event) => (dragging ? fromPointer(event) : undefined)}
        onPointerUp={() => setDragging(false)}
        onPointerCancel={() => setDragging(false)}
      >
        <div className="absolute inset-x-0 top-1/2 h-3 -translate-y-1/2 overflow-hidden rounded-full bg-muted">
          <span
            className="absolute inset-y-0 left-0 w-(--to) rounded-full bg-chart-1 opacity-35 motion-safe:transition-all motion-safe:duration-700 motion-safe:ease-out"
            // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
            style={{ "--to": seen ? at(forecast) : "0%" } as CSSProperties}
          />
          <span
            className="absolute inset-y-0 left-0 w-(--to) rounded-full bg-chart-1 motion-safe:transition-all motion-safe:delay-100 motion-safe:duration-700 motion-safe:ease-out"
            // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
            style={{ "--to": seen ? at(spent) : "0%" } as CSSProperties}
          />
        </div>
        {MARKERS.map((mark) => (
          <span
            key={mark}
            aria-hidden="true"
            className={cn("absolute top-1/2 left-(--at) h-5 w-px -translate-y-1/2", mark === 100 ? "bg-foreground" : "bg-border")}
// SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
            style={{ "--at": at((budget * mark) / 100) } as CSSProperties}
          />
        ))}
        <div
          role="slider"
          tabIndex={0}
          aria-label="Alert level"
          aria-valuemin={ALERT_MIN}
          aria-valuemax={ALERT_MAX}
          aria-valuenow={alert}
          aria-valuetext={`${alert} percent of the budget, ${formatMoney(alertAmount)}`}
          onKeyDown={(event) => {
            const next = nextAlert(event.key, event.shiftKey, alert);
            if (next === null) return;
            event.preventDefault();
            onAlert(next);
          }}
          className={cn(
            "group absolute inset-y-0 left-(--at) -ml-3 flex w-6 cursor-grab justify-center outline-none active:cursor-grabbing",
            dragging ? undefined : "motion-safe:transition-all motion-safe:duration-200 motion-safe:ease-out",
          )}
// SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
          style={{ "--at": at(alertAmount) } as CSSProperties}
        >
          <span className="h-full w-0.5 rounded-full bg-chart-4" />
          <span className="absolute top-1/2 size-4 -translate-y-1/2 rounded-full border-2 border-chart-4 bg-card shadow-sm group-focus-visible:ring-2 group-focus-visible:ring-ring group-focus-visible:ring-offset-2 group-focus-visible:ring-offset-card" />
        </div>
      </div>
      <div aria-hidden="true" className="relative h-4 text-xs text-muted-foreground tabular-nums">
        {/* 90 sits too close to 100 to label on a phone; it stays a mark and a Page key stop. */}
        {MARKERS.filter((mark) => mark !== 90).map((mark) => (
          <span
            key={mark}
            className="absolute left-(--at) -translate-x-1/2"
            // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
            style={{ "--at": at((budget * mark) / 100) } as CSSProperties}
          >
            {mark}%
          </span>
        ))}
      </div>
    </div>
  );
}
